def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    if n >= 99:
        return 'D'

    last_m, last_o = history[-1]

    opp_d = 0
    my_d = 0
    for m, o in history:
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    opp_c = n - opp_d
    opp_rate = opp_c / n

    recent = history[-15:]
    rec_len = len(recent)
    rec_opp_c = sum(1 for _, o in recent if o == 'C')
    rec_rate = rec_opp_c / rec_len

    ad_c = 0
    ad_d = 0
    ac_c = 0
    ac_d = 0
    for i in range(1, n):
        prev_me = history[i - 1][0]
        cur_opp = history[i][1]
        if prev_me == 'D':
            if cur_opp == 'C':
                ad_c += 1
            else:
                ad_d += 1
        else:
            if cur_opp == 'C':
                ac_c += 1
            else:
                ac_d += 1

    if last_m == 'D' and last_o == 'D':
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'D':
            return 'C'
        if my_d > opp_d + 1:
            return 'C'
        if opp_rate > 0.7 and rec_opp_c * 4 >= 3 * rec_len:
            if rng.random() < 0.55:
                return 'C'

    if n < 4:
        return 'C' if last_o == 'C' else 'D'

    exploit = False

    if opp_rate > 0.80 and rec_rate > 0.80:
        if ad_c >= 2 and ad_c >= ad_d + 2:
            exploit = True
        elif ad_c >= 1 and ad_d == 0 and opp_rate > 0.96 and rec_rate > 0.96:
            exploit = True

    if ad_c >= 2 and ad_c > ad_d and ac_d >= 2 and ac_d > ac_c:
        if opp_rate >= 0.50 and rec_rate >= 0.35:
            exploit = True

    if exploit:
        return 'D'

    if last_m == 'D' and last_o == 'C' and opp_rate > 0.70 and rec_rate > 0.40:
        return 'C'

    if opp_rate < 0.30 or rec_rate < 0.25:
        return 'D'

    if n < 10:
        return 'C' if last_o == 'C' else 'D'

    if last_o == 'D':
        recent5 = history[-5:]
        rec5_d = sum(1 for _, o in recent5 if o == 'D')

        if rec5_d >= 2:
            return 'D'

        if n >= 95:
            return 'D'

        if opp_rate > 0.85 and rec_rate > 0.75:
            return 'D' if rng.random() < 0.75 else 'C'

        if my_d > opp_d + 2 and opp_rate > 0.65:
            return 'C' if rng.random() < 0.70 else 'D'

        return 'D' if rng.random() < 0.85 else 'C'

    if rec_rate < 0.50:
        return 'D' if rng.random() < 0.50 else 'C'

    if n >= 95:
        if opp_rate > 0.90 and rec_rate > 0.90:
            return 'C'
        return 'D'

    return 'C'
